"""End-to-end closed-loop tracking tests.

These are the acceptance tests: plant -> synthetic sensors -> estimator ->
controller -> board -> plant, tracking a **real** SlewOS plan, with the truth
attitude and rate used only to evaluate errors afterwards.

Two cases, deliberately kept distinguishable:

* ``slewos`` -- a one-axis rest-to-rest plan generated by the real FA01 planner,
  which is the only planner scope that exists.
* ``3d`` -- a nontrivial 3D attitude target with an **externally supplied**
  schedule. This exercises 3D pointing but is *not* planner output, and the
  result record says so.
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pytest

from pocketadcs_sim.adcs import quaternions as quat
from pocketadcs_sim.adcs.closed_loop import (
    ClosedLoopConfig,
    reference_attitude,
    run_closed_loop,
)
from pocketadcs_sim.adcs.slewos_adapter import SLEWOS_DEFAULT_PATH

SLEWOS_TOLERANCE_DEG = 0.5

#: Start and target for the 3D case: 0.3 rad about body +X into a 0.7 rad
#: rotation about a generic axis, i.e. **38.4 deg** apart, not 0.3 rad.
THREE_D_START = quat.from_axis_angle(np.array([1.0, 0.0, 0.0]), 0.3)
THREE_D_TARGET = quat.from_axis_angle(np.array([0.3, 0.8, 0.5]), 0.7)


def _angle_deg(a: np.ndarray, b: np.ndarray) -> float:
    return quat.rotation_angle_rad(quat.error_quaternion(b, a)) * 180.0 / np.pi


def real_run_dir() -> Path:
    """Locate a real FA01 study A run with results and a manifest."""
    import glob

    candidates = sorted(
        glob.glob(str(SLEWOS_DEFAULT_PATH / "results" / "fa01" / "fa01_a*" / "raw.jsonl"))
    )
    if not candidates:
        pytest.skip("no FA01 study A results found in the sibling repo")
    return Path(candidates[-1]).parent


def test_ideal_slewos_schedule_is_tracked_within_tolerance() -> None:
    """A real one-axis SlewOS plan is tracked to well under a degree.

    Ideal sensors, so this tolerance measures the *loop*, not sensor noise: the
    estimator sees a perfect TRIAD fix whenever the sun is lit.
    """
    run = real_run_dir()
    config = ClosedLoopConfig(
        slewos_run_dir=str(run), slewos_case_id="a2-00000", slewos_method="DO"
    )

    result = run_closed_loop(config)

    assert result.error["final_attitude_error_deg"] < SLEWOS_TOLERANCE_DEG
    assert result.error["max_attitude_error_deg"] < SLEWOS_TOLERANCE_DEG
    assert result.planner["order"] == [1, 0]
    assert result.planner["is_planner_generated"] is True


def test_slewos_run_covers_the_whole_planned_maneuver() -> None:
    """A SlewOS run must last as long as the plan, and finish on the planner's angle.

    Otherwise the reported tracking error is measured mid-maneuver against a
    still-moving reference: the loop can hold 0.01 deg at t = 300 s while the
    vehicle is 32 deg from where the plan says it ends up, and every "it
    tracks the plan" statement is about a truncated plan.
    """
    run = real_run_dir()
    config = ClosedLoopConfig(
        slewos_run_dir=str(run), slewos_case_id="a2-00000", slewos_method="DO"
    )

    result = run_closed_loop(config)
    planned_s = result.planner["total_duration_s"]

    # The step grid cannot land exactly on an arbitrary plan duration, so the
    # run must reach the end of the maneuver to within one control period --
    # not merely some fraction of it.
    assert result.time_series()[-1]["time_s"] == pytest.approx(
        planned_s, abs=config.dt_s
    )
    # The plant really is on the planner's final attitude, not merely near a
    # reference that happens to sit there.
    assert result.plant["final_attitude_error_to_target_deg"] < SLEWOS_TOLERANCE_DEG
    assert _angle_deg(
        np.asarray(result.plant["commanded_target_attitude"], dtype=float),
        np.asarray(result.plant["final_attitude"], dtype=float),
    ) < SLEWOS_TOLERANCE_DEG


def _three_d_config() -> ClosedLoopConfig:
    return ClosedLoopConfig(
        target_attitude=THREE_D_TARGET,
        start_attitude=THREE_D_START,
        duration_s=600.0,
    )


def test_reference_starts_on_start_and_ends_exactly_on_target() -> None:
    """The externally supplied reference must actually reach the commanded target.

    Pinned independently of the plant: a reference that ends somewhere other
    than the target is vacuous, because the plant tracks the reference
    perfectly either way and the reported error stays small.
    """
    config = _three_d_config()

    at_start = reference_attitude(config, 0.0, 600.0)
    at_end = reference_attitude(config, 600.0, 600.0)

    assert _angle_deg(THREE_D_START, at_start) == pytest.approx(0.0, abs=1e-12)
    assert _angle_deg(THREE_D_TARGET, at_end) == pytest.approx(0.0, abs=1e-12)


def test_reference_error_decreases_monotonically_to_zero() -> None:
    """A smoothstep reference must not overshoot, stall short, or reverse."""
    config = _three_d_config()
    total = 600.0

    errors = [
        _angle_deg(
            THREE_D_TARGET, reference_attitude(config, t, total)
        )
        for t in np.linspace(0.0, total, 601)
    ]

    assert errors[0] == pytest.approx(_angle_deg(THREE_D_START, THREE_D_TARGET))
    assert errors[-1] == pytest.approx(0.0, abs=1e-12)
    assert all(
        later <= earlier + 1e-9
        for earlier, later in zip(errors, errors[1:], strict=False)
    )


def test_ideal_3d_target_is_tracked_within_tolerance() -> None:
    """A nontrivial 3D attitude target is reached from an offset start.

    The schedule here is supplied by this test, not by the planner; the result
    record must not claim planner support for it.

    The plant starts **38.4 deg** from the target (not 0.3 rad), so
    ``max_attitude_error_deg`` is dominated by that commanded offset; what
    matters is that the vehicle finishes *on* the target.
    """
    result = run_closed_loop(_three_d_config())

    assert result.error["final_attitude_error_deg"] < SLEWOS_TOLERANCE_DEG
    assert result.planner["is_planner_generated"] is False
    assert "externally supplied" in result.planner["source"]

    # The decisive assertion: the plant's final *truth* attitude, scored
    # against the commanded target rather than against the reference it was
    # given. Tracking the reference well is not the same as pointing at the
    # target.
    assert result.plant["final_attitude_error_to_target_deg"] < SLEWOS_TOLERANCE_DEG
    assert _angle_deg(THREE_D_TARGET, result.plant["final_attitude"]) < (
        SLEWOS_TOLERANCE_DEG
    )

    # After the transient the error must stay small, not merely end small.
    settled = [
        row["truth_attitude_error_deg"]
        for row in result.time_series()
        if row["time_s"] >= 30.0
    ]
    assert max(settled) < 1.0


def test_result_reports_a_measured_truth_cross_check() -> None:
    """The record must carry a *measured* truth cross-check, not a hardcoded flag.

    An earlier version of this test asserted ``result.truth_leakage is False``.
    That field was a dataclass default that no code path ever assigned, so the
    assertion compared ``False`` with ``False`` and would have passed even if
    truth had been threaded straight into the controller. The field is gone; the
    run now measures the actual quantity of interest -- how far the attitude the
    controller was handed is from the plant's truth attitude -- and this test
    pins that the measurement exists, is finite, and is non-zero in a
    configuration where the two genuinely differ.

    The stronger, behavioural check of the same property is
    :func:`test_loop_follows_a_biased_estimate_rather_than_the_plant`.
    """
    config = ClosedLoopConfig(
        duration_s=260.0, sensors="noisy", eclipse_windows=((60.0, 140.0),)
    )

    result = run_closed_loop(config)

    cross_check = result.truth_cross_check
    assert set(cross_check) == {
        "max_controller_input_vs_truth_deg",
        "final_controller_input_vs_truth_deg",
    }
    # Non-zero: with gyro bias, sensor noise and a commanded eclipse the
    # estimate is measurably not the truth. A cross-check that can only ever
    # read zero would be as vacuous as the flag it replaced.
    assert cross_check["max_controller_input_vs_truth_deg"] > 0.1
    assert np.isfinite(cross_check["final_controller_input_vs_truth_deg"])
    # The per-step measurement must be in the time series too, so the CSV a
    # reader gets is the same evidence rather than a summary of nothing.
    per_step = [row["controller_input_vs_truth_deg"] for row in result.time_series()]
    assert max(per_step) == pytest.approx(
        cross_check["max_controller_input_vs_truth_deg"], rel=1e-9
    )
    # And the unearned flag is gone rather than quietly reappearing.
    assert "truth_leakage" not in result.to_dict()
    assert "truth_used_for" not in result.to_dict()


def _record_seams(monkeypatch: pytest.MonkeyPatch) -> dict[str, list[np.ndarray]]:
    """Wrap the loop's estimator, controller and plant to record their states.

    This observes the real data path rather than trusting a self-report: the
    attitude handed to ``AttitudeController.compute``, the estimator's attitude
    at the same instant, and the plant's truth attitude.

    All three are sampled at the *same point in the loop* -- inside
    ``controller.compute``. Sampling the plant from ``step_rk4`` instead would
    be one step late (the controller runs first), which quietly compares this
    step's command against the previous step's truth; the numbers are close
    enough to look right, which is worse than an obvious misalignment.
    """
    import pocketadcs_sim.adcs.closed_loop as loop_module

    records: dict[str, list[np.ndarray]] = {
        "controller": [],
        "estimator": [],
        "plant": [],
    }
    plants: list[object] = []

    real_controller = loop_module.AttitudeController
    real_estimator = loop_module.OnboardAttitudeEstimator
    real_plant = loop_module.TruthPlant

    class RecordingController(real_controller):  # type: ignore[misc, valid-type]
        def compute(
            self,
            estimated_attitude,
            estimated_rate_rad_s,
            desired_attitude,
            wheel_axes=None,
        ):
            records["controller"].append(
                np.array(estimated_attitude, dtype=float, copy=True)
            )
            records["plant"].append(
                np.array(plants[-1].attitude, dtype=float, copy=True)
            )
            return super().compute(
                estimated_attitude, estimated_rate_rad_s, desired_attitude, wheel_axes
            )

    class RecordingEstimator(real_estimator):  # type: ignore[misc, valid-type]
        def update(self, time_s, gyro_body_rad_s, absolute=None):
            super().update(time_s, gyro_body_rad_s, absolute)
            records["estimator"].append(np.array(self.attitude, dtype=float, copy=True))

    class RecordingPlant(real_plant):  # type: ignore[misc, valid-type]
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            plants.append(self)

    monkeypatch.setattr(loop_module, "AttitudeController", RecordingController)
    monkeypatch.setattr(loop_module, "OnboardAttitudeEstimator", RecordingEstimator)
    monkeypatch.setattr(loop_module, "TruthPlant", RecordingPlant)
    return records


def test_controller_is_handed_the_estimate_and_not_the_plant_attitude(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The controller's attitude argument is the estimator's, bit for bit.

    Asserting on the seam rather than on a reported flag means this test fails
    the moment ``plant.attitude`` is passed to the controller instead. It also
    pins that the two candidates are *distinguishable* in this configuration,
    so the equality check above is not satisfied by both sides being the same
    number.
    """
    records = _record_seams(monkeypatch)
    config = ClosedLoopConfig(
        duration_s=260.0, sensors="noisy", eclipse_windows=((60.0, 140.0),)
    )

    result = run_closed_loop(config)

    controller_input = records["controller"]
    estimate = records["estimator"]
    truth = records["plant"]
    assert len(controller_input) == len(estimate) == len(truth) > 0

    # What the controller saw is exactly the estimator's attitude...
    for handed, estimated in zip(controller_input, estimate, strict=True):
        assert _angle_deg(estimated, handed) == pytest.approx(0.0, abs=1e-12)

    # ...and in this configuration the estimator is measurably not the truth,
    # so the check above discriminates rather than being vacuous.
    separation = max(_angle_deg(t, e) for t, e in zip(truth, estimate, strict=True))
    assert separation > 0.1
    # The controller was never handed the truth, even at the step where the
    # two differ most.
    worst = max(
        _angle_deg(t, c) for t, c in zip(truth, controller_input, strict=True)
    )
    assert worst > 0.1
    assert result.truth_cross_check["max_controller_input_vs_truth_deg"] == (
        pytest.approx(worst, rel=1e-9)
    )


def test_loop_follows_a_biased_estimate_rather_than_the_plant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A deliberately wrong sensor fix must drag the vehicle off target.

    This is the end-to-end version of the truth-ownership rule, and it cannot
    pass by accident: the sensors report every absolute fix rotated by a known
    10 deg body-frame bias, so the estimator's answer is wrong by that bias
    while the plant's truth attitude is unaffected. If any part of the loop
    consumed truth, the vehicle would still converge on the commanded target.
    Because the loop is closed through the estimate, the bias instead survives
    into the physical response.
    """
    import pocketadcs_sim.adcs.closed_loop as loop_module

    bias = quat.from_axis_angle(np.array([0.0, 0.0, 1.0]), np.deg2rad(10.0))
    real_sensors = loop_module.SyntheticSensors

    class BiasedSensors(real_sensors):  # type: ignore[misc, valid-type]
        def measure(self, t_s, attitude, body_rate):
            # Rotate the attitude the sensors report. The plant is untouched:
            # this is a sensor fault, not a change of physics.
            return super().measure(t_s, quat.multiply(bias, attitude), body_rate)

    monkeypatch.setattr(loop_module, "SyntheticSensors", BiasedSensors)

    config = _three_d_config()
    result = run_closed_loop(config)

    bias_deg = 10.0
    # The estimate is wrong by the injected bias...
    assert result.error["final_estimate_error_deg"] == pytest.approx(
        bias_deg, abs=0.05
    )
    # ...and that error is carried into the vehicle's actual attitude: the loop
    # settles where the biased estimate says the target is, not on the target.
    assert result.plant["final_attitude_error_to_target_deg"] == pytest.approx(
        bias_deg, abs=0.05
    )
    # The same holds against the reference: the loop tracks what the reference
    # looks like *through the biased estimate*, so it settles 10 deg away from
    # it as well. A loop that was secretly using truth would report < 0.5 deg
    # here, which is exactly why this test discriminates.
    assert result.error["final_attitude_error_deg"] == pytest.approx(
        bias_deg, abs=0.05
    )


def test_ideal_run_cross_check_is_zero_because_the_fix_is_exact_at_the_sample(
) -> None:
    """Zero in an ideal run is the expected reading, and is not leakage.

    With ideal sensors the TRIAD fix is exact *at the sample instant*, so the
    attitude handed to the controller equals the plant's truth attitude to
    machine precision and the cross-check reads 0.0. Divergence then appears
    only across the plant step, which is why the post-step estimator error in
    the same run is larger (0.0096 deg for the 3D case).

    Left unexplained, a 0.0 in the artifact looks exactly like the bug the
    cross-check exists to catch, and the natural "fix" is to loosen the
    measurement. This pins the correct reading: the cross-check is bounded
    above by the post-step estimate error, is zero only when the loop is handed
    an exact fix, and becomes non-zero as soon as the fix is imperfect.
    """
    result = run_closed_loop(_three_d_config())

    cross_check = result.truth_cross_check["max_controller_input_vs_truth_deg"]
    post_step = result.error["max_estimate_error_deg"]

    assert cross_check == pytest.approx(0.0, abs=1e-9)
    assert post_step > cross_check, (
        "the post-step estimate error must be the larger number, otherwise the "
        "ideal cross-check reading is not the one this test explains"
    )
    assert cross_check <= post_step + 1e-12


def test_estimator_and_plant_agree_when_sensors_are_perfect() -> None:
    """With ideal sensors the estimate tracks truth to numerical precision."""
    config = ClosedLoopConfig(duration_s=120.0)

    result = run_closed_loop(config)

    assert result.error["final_estimate_error_deg"] < 1e-3


def test_eclipse_degrades_then_recovers_rather_than_diverging() -> None:
    """A commanded eclipse must not blow the estimate up, and must recover.

    This is the behaviour the real ADS exists for: coast on the gyro through
    darkness, snap back when the sun returns.
    """
    config = ClosedLoopConfig(duration_s=260.0, eclipse_windows=((60.0, 140.0),))

    result = run_closed_loop(config)

    during = result.error["max_attitude_error_deg_during_eclipse"]
    after = result.error["final_attitude_error_deg"]
    assert after < SLEWOS_TOLERANCE_DEG
    assert np.isfinite(during)
    assert during < 10.0, "eclipse coasting should degrade, not diverge"


def test_wheel_limits_are_reported_and_respected() -> None:
    """The record reports achieved wheel speeds against the bound, and saturation."""
    config = ClosedLoopConfig(duration_s=300.0)

    result = run_closed_loop(config)

    wheels = result.wheels
    assert wheels["max_speed_bound_rad_s"] > 0.0
    assert wheels["max_abs_wheel_speed_rad_s"] <= wheels["max_speed_bound_rad_s"] * 1.001
    assert "saturated_steps" in wheels
    assert "max_acceleration_cap_rad_s2" in wheels


def test_result_is_written_as_json_and_csv_on_disk(tmp_path: Path) -> None:
    """Measurements and configuration are real files, not invented values."""
    config = ClosedLoopConfig(duration_s=120.0, output_dir=str(tmp_path))

    result = run_closed_loop(config)

    written = json.loads(Path(result.output_json_path).read_text(encoding="utf-8"))
    assert written["error"]["final_attitude_error_deg"] == pytest.approx(
        result.error["final_attitude_error_deg"], rel=1e-12
    )
    assert written["config"]["dt_s"] == config.dt_s
    csv_path = Path(result.output_csv_path)
    assert csv_path.exists()
    header = csv_path.read_text(encoding="utf-8").splitlines()[0]
    assert "time_s" in header and "truth_attitude_error_deg" in header


def test_results_are_deterministic_for_a_fixed_configuration() -> None:
    """Same config twice gives the same trajectory (no hidden randomness)."""
    config = ClosedLoopConfig(duration_s=120.0)

    first = run_closed_loop(config)
    second = run_closed_loop(config)

    assert first.error["final_attitude_error_deg"] == pytest.approx(
        second.error["final_attitude_error_deg"], rel=1e-12
    )
    assert first.time_series() == second.time_series()


def test_invalid_configuration_is_rejected() -> None:
    """Bad configuration fails loudly rather than producing a meaningless run."""
    with pytest.raises(ValueError):
        ClosedLoopConfig(dt_s=0.0)
    with pytest.raises(ValueError):
        ClosedLoopConfig(dt_s=-0.01)
    with pytest.raises(ValueError):
        ClosedLoopConfig(duration_s=0.0)
    with pytest.raises(ValueError):
        run_closed_loop(ClosedLoopConfig(slewos_run_dir="does/not/exist"))


def test_eclipse_window_must_be_ordered_and_inside_the_run() -> None:
    """Nonsensical eclipse windows are a configuration error, not a silent no-op."""
    with pytest.raises(ValueError):
        ClosedLoopConfig(duration_s=100.0, eclipse_windows=((50.0, 20.0),))
    with pytest.raises(ValueError):
        ClosedLoopConfig(duration_s=100.0, eclipse_windows=((10.0, 500.0),))


def test_commanded_vs_applied_torque_disagree_when_saturated() -> None:
    """A saturating run must show commanded and applied differing, and say why.

    The board is transparent when unsaturated, so this also confirms the
    unsaturated case leaves the two identical.
    """
    easy = run_closed_loop(ClosedLoopConfig(duration_s=120.0))
    assert easy.wheels["max_commanded_applied_gap_nm"] == pytest.approx(0.0, abs=1e-12)

    hard = run_closed_loop(
        ClosedLoopConfig(duration_s=120.0, proportional_gain=50.0)
    )
    assert hard.wheels["max_commanded_applied_gap_nm"] > 0.0
    assert hard.wheels["saturated_steps"] > 0


def test_missing_controller_snapshot_fails_the_run_loudly(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A controller that records no attitude must not yield a quiet zero.

    The cross-check is the measured evidence that the controller worked from
    the estimate rather than from truth. If ``last_estimated_attitude`` were
    ever absent, the two available responses are both wrong: substituting a
    caller-held value scores what the caller *believed* it sent (the same
    defect as the deleted ``truth_leakage`` flag), and scoring 0.0 fabricates a
    perfect result out of a missing measurement. The run must fail instead.
    """
    import pocketadcs_sim.adcs.closed_loop as loop_module

    real_controller = loop_module.AttitudeController

    class ForgetfulController(real_controller):  # type: ignore[misc, valid-type]
        def compute(self, *args, **kwargs):  # type: ignore[no-untyped-def]
            torque = super().compute(*args, **kwargs)
            self.last_estimated_attitude = None
            return torque

    monkeypatch.setattr(loop_module, "AttitudeController", ForgetfulController)

    with pytest.raises(RuntimeError, match="last_estimated_attitude"):
        run_closed_loop(ClosedLoopConfig(duration_s=5.0))
